			$prod->update_meta_data( '_dp_pack_qty', $qty );

			/* v1.25: savikaina = bazes savikaina x N; jei bazes nera — trinam sena. */
			$bsav = self::savikaina( $bid );
			if ( $bsav !== null && $bsav > 0 ) { $prod->update_meta_data( '_cost_price', round( $bsav * $qty, 4 ) ); }
